(1154343, 144219, 30861, '<td valign="top">You got my 10. This SO stands out ahove every other image in the challenge for its emotional purity. I hope it doesn''t get scored down for the relative scarcity of pink in the image.</td>', 'You got my 10. This SO stands out ahove every other image in the challenge for its emotional purity. I hope it doesn''t get scored down for the relative scarcity of pink in the image.', '2005-02-07 02:42:23.000000', NULL, 1),
(1154344, 144332, 30861, '<td valign="top">A 10 from me. Lovingly composed and rendered, determinedly low-key on the pink, subtle and effective. The luminous button makes the image.</td>', 'A 10 from me. Lovingly composed and rendered, determinedly low-key on the pink, subtle and effective. The luminous button makes the image.', '2005-02-07 02:43:28.000000', NULL, 1),
