(1154465, 144022, 18552, '<td valign="top">Very cute with a lot of pathos. Love the expression on her face and all the clashing pinkness.</td>', 'Very cute with a lot of pathos. Love the expression on her face and all the clashing pinkness.', '2005-02-07 05:40:45.000000', NULL, 1),
(1154466, 144479, 23478, '<td valign="top">Great shot, just a tad oversharpened.</td>', 'Great shot, just a tad oversharpened.', '2005-02-07 05:40:59.000000', NULL, 1),
(1154467, 144009, 22970, '<td valign="top">Wow I just love Old cars. You have captured the moment and makes me feel as if I am there. Hard to take a photograph in this kind of lighting but you did it. I love the reflections, color, lighting, and DOF. And a great job at keeping the chrome real, it stands out. What a beautiful pink tone. Good luck in the challenge 9!</td>', 'Wow I just love Old cars. You have captured the moment and makes me feel as if I am there. Hard to take a photograph in this kind of lighting but you did it. I love the reflections, color, lighting, and DOF. And a great job at keeping the chrome real, it stands out. What a beautiful pink tone. Good luck in the challenge 9!', '2005-02-07 05:41:34.000000', NULL, 1),
(1154468, 143859, 18552, '<td valign="top">Lovely. The flamingos are so pretty and a perfect shade of pink. The pink reflections in the water are nice, too. Great Job.</td>', 'Lovely. The flamingos are so pretty and a perfect shade of pink. The pink reflections in the water are nice, too. Great Job.', '2005-02-07 05:41:44.000000', NULL, 1),
(1154469, 143995, 23478, '<td valign="top">Wonderful detail.</td>', 'Wonderful detail.', '2005-02-07 05:41:51.000000', NULL, 1),
