(1154695, 144515, 30505, '<td valign="top">Great Title!</td>', 'Great Title!', '2005-02-07 09:00:21.000000', NULL, 1),
(1154696, 142894, 14448, '<td valign="top">Looks more orange than pink on my monitor.  Excellent lighting and composition.  Love how you have captured the texture of the petal.  Certainly one of the better ''flower'' entries of the composition, colour question notwithstanding.</td>', 'Looks more orange than pink on my monitor.  Excellent lighting and composition.  Love how you have captured the texture of the petal.  Certainly one of the better ''flower'' entries of the composition, colour question notwithstanding.', '2005-02-07 09:00:25.000000', NULL, 1),
