(1155186, 144375, 31865, '<td valign="top">one of the better flower shots.  i love the even tone and soft shadow.</td>', 'one of the better flower shots.  i love the even tone and soft shadow.', '2005-02-07 14:33:33.000000', NULL, 1),
(1155187, 143945, 31865, '<td valign="top">the look on her face is priceless.  great shot.</td>', 'the look on her face is priceless.  great shot.', '2005-02-07 14:34:10.000000', NULL, 1),
(1155188, 143446, 18194, '<td valign="top">I think this is a great photo, I will be very interested to see how it does.. a 10 from me.<br/>I fear there are others on this site who will not give this a good score.<br/></td>', 'I think this is a great photo, I will be very interested to see how it does.. a 10 from me.I fear there are others on this site who will not give this a good score.', '2005-02-07 14:34:30.000000', NULL, 1),
