INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1155899, 143094, 25464, '<td valign="top">Interesting, great light, spectacular eyes, meets the challenge.  This, I am predicting, will be a ribbon.  Probably blue. 10.</td>', 'Interesting, great light, spectacular eyes, meets the challenge.  This, I am predicting, will be a ribbon.  Probably blue. 10.', '2005-02-07 20:38:49.000000', NULL, 1),
(1155900, 144447, 25464, '<td valign="top">Interesting compositional choice.  nice color. 9.</td>', 'Interesting compositional choice.  nice color. 9.', '2005-02-07 20:39:20.000000', NULL, 1),
(1155901, 142524, 25464, '<td valign="top">Very well done, but very predictable.  Detail is good in the center, and color is nice.</td>', 'Very well done, but very predictable.  Detail is good in the center, and color is nice.', '2005-02-07 20:40:20.000000', NULL, 1),
(1155903, 143991, 30861, '<td valign="top">This simply is not pink. By any stretch of the imagination. Nice shot though.</td>', 'This simply is not pink. By any stretch of the imagination. Nice shot though.', '2005-02-07 20:42:20.000000', NULL, 1),
(1155904, 144256, 25464, '<td valign="top">This is a great idea, but I am wondering why you would choose this composition.  The prettiest part of the glass is removed here.  The colors are excellent, and the focus is great.  The lipstick is a nice touch as well.  I think composition is the only element lacking IMO.</td>', 'This is a great idea, but I am wondering why you would choose this composition.  The prettiest part of the glass is removed here.  The colors are excellent, and the focus is great.  The lipstick is a nice touch as well.  I think composition is the only element lacking IMO.', '2005-02-07 20:42:32.000000', NULL, 1),
(1155905, 144051, 30861, '<td valign="top">This is an absolutely beautiful image of an extremely red-orange flamingo. It just doesn''t say pink to me, but I''m scoring it above average so I''m doing you no damage.</td>', 'This is an absolutely beautiful image of an extremely red-orange flamingo. It just doesn''t say pink to me, but I''m scoring it above average so I''m doing you no damage.', '2005-02-07 20:43:46.000000', NULL, 1),
(1155906, 143847, 25464, '<td valign="top">Interesting composition.  I am not wild about the choice of flower here, but it is different.</td>', 'Interesting composition.  I am not wild about the choice of flower here, but it is different.', '2005-02-07 20:43:59.000000', NULL, 1),
(1155907, 144518, 25464, '<td valign="top">It will probably get beat up, but not by me.  Very pretty.</td>', 'It will probably get beat up, but not by me.  Very pretty.', '2005-02-07 20:44:33.000000', NULL, 1),
(1155911, 144471, 25464, '<td valign="top">Great use of pink, and great expression.  The lighting is flat though.  It looks like your light source is hitting the top of the hat and leaving the eyes in the dark.</td>', 'Great use of pink, and great expression.  The lighting is flat though.  It looks like your light source is hitting the top of the hat and leaving the eyes in the dark.', '2005-02-07 20:46:25.000000', NULL, 1),
(1155915, 144250, 25464, '<td valign="top">Very nicely done.  Interesting clothing choices.  Focus and light are perfect for this type of shot.</td>', 'Very nicely done.  Interesting clothing choices.  Focus and light are perfect for this type of shot.', '2005-02-07 20:47:26.000000', NULL, 1),
(1155917, 144219, 25464, '<td valign="top">Very cute. Those eyes just sparkle.</td>', 'Very cute. Those eyes just sparkle.', '2005-02-07 20:47:56.000000', NULL, 1),
(1155919, 144335, 25464, '<td valign="top">This is pretty soft, but has an almost satiny quality.  I like it, but it is also very predictable.</td>', 'This is pretty soft, but has an almost satiny quality.  I like it, but it is also very predictable.', '2005-02-07 20:48:47.000000', NULL, 1),
(1155921, 144342, 25464, '<td valign="top">This is maybe not the best carnation I have ever seen, but the picture is taken perfectly.  Background and foreground element work together wonderfully.</td>', 'This is maybe not the best carnation I have ever seen, but the picture is taken perfectly.  Background and foreground element work together wonderfully.', '2005-02-07 20:50:45.000000', NULL, 1),
(1155927, 143754, 25464, '<td valign="top">This is a beautifully taken shot and a great idea.  The crop is a bit too tight for my taste, but that is just opinion.</td>', 'This is a beautifully taken shot and a great idea.  The crop is a bit too tight for my taste, but that is just opinion.', '2005-02-07 20:53:32.000000', NULL, 1),
(1155929, 142982, 18194, '<td valign="top">yikes!!! way over processed or my tastes.</td>', 'yikes!!! way over processed or my tastes.', '2005-02-07 20:53:53.000000', NULL, 1),
(1155932, 143325, 18194, '<td valign="top">A very good clean shot. Well lit and well composed..8</td>', 'A very good clean shot. Well lit and well composed..8', '2005-02-07 20:54:40.000000', NULL, 1),
(1155936, 144524, 25464, '<td valign="top">Very cute different idea.  I can''t see it hanging on my wall, but I could see it on a teenagers.  The only draw back here is the shadow on the wall.  Eliminate that and maybe a bit tighter crop eliminating the bend in the knee, and I think you would have a real gem.</td>', 'Very cute different idea.  I can''t see it hanging on my wall, but I could see it on a teenagers.  The only draw back here is the shadow on the wall.  Eliminate that and maybe a bit tighter crop eliminating the bend in the knee, and I think you would have a real gem.', '2005-02-07 20:56:07.000000', NULL, 1),
(1155938, 143461, 18194, '<td valign="top">The face of the broken heart seem overly dark.</td>', 'The face of the broken heart seem overly dark.', '2005-02-07 20:56:46.000000', NULL, 1),
(1155940, 144408, 18194, '<td valign="top">The focus could be better on this.</td>', 'The focus could be better on this.', '2005-02-07 20:57:19.000000', NULL, 1),
(1155941, 143509, 23394, '<td valign="top">i can only imagine how this shot came to be...<br/>it does meet the challenge, but in a definite snapshotty way.  as she appears amenable enough to having her picture taken, it''s too bad you couldn''t have caught an image that was a bit more engaging.</td>', 'i can only imagine how this shot came to be...it does meet the challenge, but in a definite snapshotty way.  as she appears amenable enough to having her picture taken, it''s too bad you couldn''t have caught an image that was a bit more engaging.', '2005-02-07 20:57:27.000000', NULL, 1),
