(1156695, 144515, 15511, '<td valign="top">Technically, very good, but not very interesting, or appealing.</td>', 'Technically, very good, but not very interesting, or appealing.', '2005-02-08 03:10:47.000000', NULL, 1),
(1156708, 144046, 15511, '<td valign="top">I think that to have something in this picture in focus would have added some focus to this image. There''s essentially nothing to to draw my eye to and keep it engaged.</td>', 'I think that to have something in this picture in focus would have added some focus to this image. There''s essentially nothing to to draw my eye to and keep it engaged.', '2005-02-08 03:16:04.000000', NULL, 1),
(1156712, 142982, 15511, '<td valign="top">This picture lacks appeal, is almost strange how the red hair seems to be the center of attention, and the pink appears to be a secondary consideration.</td>', 'This picture lacks appeal, is almost strange how the red hair seems to be the center of attention, and the pink appears to be a secondary consideration.', '2005-02-08 03:19:14.000000', NULL, 1),
(1156717, 143971, 15511, '<td valign="top">The hearts are out of focus, but more importantly, the reliance on the background lighting makes the hand appear blue to the point of un-natural appeal.</td>', 'The hearts are out of focus, but more importantly, the reliance on the background lighting makes the hand appear blue to the point of un-natural appeal.', '2005-02-08 03:21:42.000000', NULL, 1),
(1156746, 142524, 19959, '<td valign="top">Quite obvious subject (much like my entry!) but this is a very good shot, one of the better flower entries.</td>', 'Quite obvious subject (much like my entry!) but this is a very good shot, one of the better flower entries.', '2005-02-08 04:09:24.000000', NULL, 1),
(1156747, 142900, 19959, '<td valign="top">Excellent candid.</td>', 'Excellent candid.', '2005-02-08 04:09:42.000000', NULL, 1),
(1156748, 142430, 19959, '<td valign="top">interesting idea, well executed</td>', 'interesting idea, well executed', '2005-02-08 04:09:56.000000', NULL, 1),
(1156749, 144352, 19959, '<td valign="top">Nice</td>', 'Nice', '2005-02-08 04:10:05.000000', NULL, 1),
(1156753, 142934, 15816, '<td valign="top">very good work!</td>', 'very good work!', '2005-02-08 04:20:18.000000', NULL, 1),
(1156767, 142986, 32749, '<td valign="top">Great compostion and colour of the cheeks is spot on.</td>', 'Great compostion and colour of the cheeks is spot on.', '2005-02-08 04:59:56.000000', NULL, 1),
(1156769, 144235, 32749, '<td valign="top">I would love to have taken this shot, brilliant.</td>', 'I would love to have taken this shot, brilliant.', '2005-02-08 05:01:14.000000', NULL, 1),
(1156770, 143094, 32749, '<td valign="top">Good composition and DOF.</td>', 'Good composition and DOF.', '2005-02-08 05:03:38.000000', NULL, 1),
(1156920, 143948, 23681, '<td valign="top">That''s just nasty.  Good photo, technically, bu just nasty.</td>', 'That''s just nasty.  Good photo, technically, bu just nasty.', '2005-02-08 08:23:54.000000', NULL, 1),
(1156928, 144093, 8522, '<td valign="top">Huge shame about the really bad noise levels on the rear pig''s rump, presumably caused by hue shifting. I love this shot otherwise!</td>', 'Huge shame about the really bad noise levels on the rear pig''s rump, presumably caused by hue shifting. I love this shot otherwise!', '2005-02-08 08:31:16.000000', NULL, 1),
(1156934, 143933, 8522, '<td valign="top">Sorry, this has gone right over my head! Interesting shot though.</td>', 'Sorry, this has gone right over my head! Interesting shot though.', '2005-02-08 08:33:49.000000', NULL, 1),
(1156948, 142443, 8522, '<td valign="top">Shame about the ugly shadow caused by the lighting. Nice subject and background, although she really needs to be a bit further away from the writing.</td>', 'Shame about the ugly shadow caused by the lighting. Nice subject and background, although she really needs to be a bit further away from the writing.', '2005-02-08 08:44:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1156956, 143740, 32818, '<td valign="top">Wow.... unbelieveble.. Looks unreal! Love it!</td>', 'Wow.... unbelieveble.. Looks unreal! Love it!', '2005-02-08 08:49:47.000000', NULL, 1),
(1156959, 143833, 15305, '<td valign="top">I really love this image. It is very sensible, well thought and well carried out. The desaturation really works in this picture.  Congratulations.</td>', 'I really love this image. It is very sensible, well thought and well carried out. The desaturation really works in this picture.  Congratulations.', '2005-02-08 08:54:52.000000', NULL, 1),
(1156979, 144051, 25655, '<td valign="top">Beautiful! (9)<br/>I really love Flamingos, and I think this is one of the best I''ve seen!<br/>Great color, fits the challenge perfectly. Nice details, althought the focus is a bit soft. It''s also a bit grainy. I''m guessing this photo was taken from a far.<br/>But still, a wonderful photo of one of the most amazing birds IMO.<br/></td>', 'Beautiful! (9)I really love Flamingos, and I think this is one of the best I''ve seen!Great color, fits the challenge perfectly. Nice details, althought the focus is a bit soft. It''s also a bit grainy. I''m guessing this photo was taken from a far.But still, a wonderful photo of one of the most amazing birds IMO.', '2005-02-08 09:11:47.000000', NULL, 1),
(1156991, 142707, 25655, '<td valign="top">the photo is gorgeous! But I don''t really find it to answer the challenge.<br/>The color of the tulip here is more orange or peach then pink, and the glow only enhances the yelow.<br/>Yet, since I realy liked this photo I gave you a 7.</td>', 'the photo is gorgeous! But I don''t really find it to answer the challenge.The color of the tulip here is more orange or peach then pink, and the glow only enhances the yelow.Yet, since I realy liked this photo I gave you a 7.', '2005-02-08 09:22:18.000000', NULL, 1),
(1156993, 144452, 25655, '<td valign="top">I just loved it!<br/>Wonderful picture, fits the challenge beautifully. Great lighting, I love the colors and the idea.<br/>The red and white creating a heart shape just makes it even more interesting. <br/>So far, the only 10 I gave out on this challenge... <br/></td>', 'I just loved it!Wonderful picture, fits the challenge beautifully. Great lighting, I love the colors and the idea.The red and white creating a heart shape just makes it even more interesting. So far, the only 10 I gave out on this challenge... ', '2005-02-08 09:24:24.000000', NULL, 1),
(1157003, 143872, 15711, '<td valign="top">Love this one for sure!!!  A ++</td>', 'Love this one for sure!!!  A ++', '2005-02-08 09:31:28.000000', NULL, 1),
(1157004, 143050, 25655, '<td valign="top">Very few of the selective desaturation photos are really leaving an impression on me. This one did!<br/>It''s so cute and funny and nice. Really made me wanna stay some more!<br/>Beautiful lighting, nice details, great work!</td>', 'Very few of the selective desaturation photos are really leaving an impression on me. This one did!It''s so cute and funny and nice. Really made me wanna stay some more!Beautiful lighting, nice details, great work!', '2005-02-08 09:32:10.000000', NULL, 1),
(1157006, 143974, 22860, '<td valign="top">Very funny, and I dont know how you photographed these fish, in my aquarium they''re very shy. Well done.</td>', 'Very funny, and I dont know how you photographed these fish, in my aquarium they''re very shy. Well done.', '2005-02-08 09:33:42.000000', NULL, 1),
(1157007, 144413, 15711, '<td valign="top">Indicative of a Texas sunset!!  Where was this taken?</td>', 'Indicative of a Texas sunset!!  Where was this taken?', '2005-02-08 09:33:53.000000', NULL, 1),
(1157008, 144265, 22860, '<td valign="top">I do not understand the title, must be me?</td>', 'I do not understand the title, must be me?', '2005-02-08 09:34:19.000000', NULL, 1),
(1157009, 144392, 22860, '<td valign="top">Nice, did you just invert the colors?</td>', 'Nice, did you just invert the colors?', '2005-02-08 09:34:37.000000', NULL, 1),
(1157010, 144268, 25655, '<td valign="top">This image is more orange then it is pink, but I love flamingos, and this one is lovely.<br/>Looks like a dream. Great effect and nice photo. 7</td>', 'This image is more orange then it is pink, but I love flamingos, and this one is lovely.Looks like a dream. Great effect and nice photo. 7', '2005-02-08 09:34:42.000000', NULL, 1),
(1157011, 143489, 18485, '<td valign="top">i love this...the girl''s serenity and that amazing hat.  says PINK to me.  9</td>', 'i love this...the girl''s serenity and that amazing hat.  says PINK to me.  9', '2005-02-08 09:35:01.000000', NULL, 1),
(1157012, 144266, 18485, '<td valign="top">so crisp and clear.  interesting crop.  not so fond of your border here but the photo is top notch and very pink. 9</td>', 'so crisp and clear.  interesting crop.  not so fond of your border here but the photo is top notch and very pink. 9', '2005-02-08 09:35:46.000000', NULL, 1),
(1157013, 144356, 22860, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2005-02-08 09:35:56.000000', NULL, 1),
(1157014, 143954, 18485, '<td valign="top">what a capture!  i''d love to think it was candid.  either way, nice take on pink 9</td>', 'what a capture!  i''d love to think it was candid.  either way, nice take on pink 9', '2005-02-08 09:36:32.000000', NULL, 1),
(1157016, 142797, 18485, '<td valign="top">timing is everything.  nice work.</td>', 'timing is everything.  nice work.', '2005-02-08 09:36:52.000000', NULL, 1),
(1157017, 143094, 25655, '<td valign="top">Returning for comment: Beautiful face, nice DOF, striking pink :-)<br/>Bumping up.</td>', 'Returning for comment: Beautiful face, nice DOF, striking pink :-)Bumping up.', '2005-02-08 09:36:59.000000', NULL, 1),
(1157018, 144275, 18485, '<td valign="top">stunning photo, great capture.  love this!  9</td>', 'stunning photo, great capture.  love this!  9', '2005-02-08 09:37:39.000000', NULL, 1),
(1157019, 144425, 22860, '<td valign="top">Beautiful, but did you edit a lot?</td>', 'Beautiful, but did you edit a lot?', '2005-02-08 09:38:14.000000', NULL, 1),
(1157021, 144140, 18485, '<td valign="top">pretty shot, great expression.  a little too much depixillating perhaps?</td>', 'pretty shot, great expression.  a little too much depixillating perhaps?', '2005-02-08 09:38:58.000000', NULL, 1),
(1157022, 144051, 22860, '<td valign="top">I think this is the best photo in the competition so far. I hope it''s gonna be one of the winning photo''s. Very beautiful, I saved it on my harddisk and e-mailed it to my mother, who loves flamingos.</td>', 'I think this is the best photo in the competition so far. I hope it''s gonna be one of the winning photo''s. Very beautiful, I saved it on my harddisk and e-mailed it to my mother, who loves flamingos.', '2005-02-08 09:39:00.000000', NULL, 1),
(1157023, 143847, 25655, '<td valign="top">Returning for comment: Clean and clear image.<br/>Something in the flower gives me a feeling of a flower in an island''s girl''s hair.<br/>Calm and peacful, despite the contrasted colors.<br/>Good work, bumping up.</td>', 'Returning for comment: Clean and clear image.Something in the flower gives me a feeling of a flower in an island''s girl''s hair.Calm and peacful, despite the contrasted colors.Good work, bumping up.', '2005-02-08 09:39:15.000000', NULL, 1),
(1157026, 144385, 18485, '<td valign="top">nice photo--maybe a little to tightly cropped on the rose.</td>', 'nice photo--maybe a little to tightly cropped on the rose.', '2005-02-08 09:40:08.000000', NULL, 1),
(1157030, 144235, 18485, '<td valign="top">wow.  great sky great shot.  8</td>', 'wow.  great sky great shot.  8', '2005-02-08 09:40:27.000000', NULL, 1),
(1157031, 144453, 18485, '<td valign="top">hahaha.  this is great...i always wondered where this guy was!  nice shot, a little flat somehow--maybe owing to the overcast day.  7</td>', 'hahaha.  this is great...i always wondered where this guy was!  nice shot, a little flat somehow--maybe owing to the overcast day.  7', '2005-02-08 09:42:38.000000', NULL, 1),
(1157035, 143079, 18485, '<td valign="top">lovely capture.  what a sky!</td>', 'lovely capture.  what a sky!', '2005-02-08 09:44:28.000000', NULL, 1),
(1157040, 144275, 22384, '<td valign="top">Adorable. Great Capture. I love how you can tell that your subject is smiling from the tiniest glimpse of her profile.</td>', 'Adorable. Great Capture. I love how you can tell that your subject is smiling from the tiniest glimpse of her profile.', '2005-02-08 09:48:24.000000', NULL, 1),
(1157045, 143762, 22384, '<td valign="top">Great shot. As and English teacher, I especially like the title. It is a poignant story. This is a fascinating shot. Thanks for sharing it. 8</td>', 'Great shot. As and English teacher, I especially like the title. It is a poignant story. This is a fascinating shot. Thanks for sharing it. 8', '2005-02-08 09:54:01.000000', NULL, 1),
(1157047, 144363, 22384, '<td valign="top">Creative, risky and unique. I like it. I needed the title to understand it, though. Thanks for pulling it together. 9</td>', 'Creative, risky and unique. I like it. I needed the title to understand it, though. Thanks for pulling it together. 9', '2005-02-08 09:55:26.000000', NULL, 1),
(1157048, 144346, 22384, '<td valign="top">Creative title. Bumping up just for that alone!</td>', 'Creative title. Bumping up just for that alone!', '2005-02-08 09:56:25.000000', NULL, 1),
(1157050, 144242, 22384, '<td valign="top">Great capture. I like the composition, the expression on your subject''s face, and the wind in her hair. Is this a studio shot? 8</td>', 'Great capture. I like the composition, the expression on your subject''s face, and the wind in her hair. Is this a studio shot? 8', '2005-02-08 09:57:52.000000', NULL, 1),
(1157051, 144110, 22384, '<td valign="top">I love it. Great capture. 8</td>', 'I love it. Great capture. 8', '2005-02-08 09:58:37.000000', NULL, 1),
(1157052, 143731, 21362, '<td valign="top">Way oversaturated. That must be intentional, but I don''t see that it adds anything to the photo.<br/> <br/>Not sure looking into someone''s nostrils is really the most flattering angle to photograph them. ;)</td>', 'Way oversaturated. That must be intentional, but I don''t see that it adds anything to the photo. Not sure looking into someone''s nostrils is really the most flattering angle to photograph them. ;)', '2005-02-08 09:59:26.000000', NULL, 1),
(1157054, 142865, 22384, '<td valign="top">Great image. Wonderful expression in your subject''s eyes! IMO, flawless! 10</td>', 'Great image. Wonderful expression in your subject''s eyes! IMO, flawless! 10', '2005-02-08 10:01:00.000000', NULL, 1),
(1157055, 144204, 21362, '<td valign="top">Good effort. I''d have removed the curly ribbon and left only the flower as the focul point. That ribbon just leads my eye away.</td>', 'Good effort. I''d have removed the curly ribbon and left only the flower as the focul point. That ribbon just leads my eye away.', '2005-02-08 10:01:02.000000', NULL, 1),
(1157059, 143933, 21362, '<td valign="top">LOL at the title.</td>', 'LOL at the title.', '2005-02-08 10:02:21.000000', NULL, 1),
(1157096, 143832, 10985, '<td valign="top">Superb! Fantastic softness and light. Very ethereal and beautiful.</td>', 'Superb! Fantastic softness and light. Very ethereal and beautiful.', '2005-02-08 10:48:44.000000', NULL, 1),
(1157098, 143754, 10985, '<td valign="top">Very interesting composition and DoF. Well lit and well done. Good luck!</td>', 'Very interesting composition and DoF. Well lit and well done. Good luck!', '2005-02-08 10:49:45.000000', NULL, 1),
(1157099, 142865, 10985, '<td valign="top">Powerful, impactful. What a look!</td>', 'Powerful, impactful. What a look!', '2005-02-08 10:50:06.000000', NULL, 1),
(1157101, 143928, 10985, '<td valign="top">Wow, were they really that pink?</td>', 'Wow, were they really that pink?', '2005-02-08 10:50:35.000000', NULL, 1),
(1157102, 143967, 10985, '<td valign="top">Beautiful lighting and composition. Good luck!</td>', 'Beautiful lighting and composition. Good luck!', '2005-02-08 10:51:32.000000', NULL, 1),
(1157107, 144452, 10985, '<td valign="top">I like this: it''s very artistic. The textures feel a bit awkward on the model, but the set-up, composition and impact are very good.</td>', 'I like this: it''s very artistic. The textures feel a bit awkward on the model, but the set-up, composition and impact are very good.', '2005-02-08 10:55:13.000000', NULL, 1),
(1157108, 143489, 10985, '<td valign="top">A pink, or even white, shirt would have made this really harmonious and would have given it more impact. The portrait is very interesting, though and the lighting is quite good.</td>', 'A pink, or even white, shirt would have made this really harmonious and would have given it more impact. The portrait is very interesting, though and the lighting is quite good.', '2005-02-08 10:56:44.000000', NULL, 1),
(1157110, 144264, 10985, '<td valign="top">Emotive and artistic.</td>', 'Emotive and artistic.', '2005-02-08 10:57:31.000000', NULL, 1),
(1157113, 144049, 10985, '<td valign="top">Very sharp! Maybe a bit too saturated, but it does give it a style. Nice composition and DoF.</td>', 'Very sharp! Maybe a bit too saturated, but it does give it a style. Nice composition and DoF.', '2005-02-08 10:59:28.000000', NULL, 1),
(1157114, 142986, 8522, '<td valign="top">A bit too NeatImaged/airbrushed for my taste. Also oversharpened.</td>', 'A bit too NeatImaged/airbrushed for my taste. Also oversharpened.', '2005-02-08 10:59:59.000000', NULL, 1),
(1157117, 144268, 10985, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2005-02-08 11:00:35.000000', NULL, 1),
(1157118, 143994, 10985, '<td valign="top">Good imagery. Nicely thought up and very well executed.</td>', 'Good imagery. Nicely thought up and very well executed.', '2005-02-08 11:01:08.000000', NULL, 1),
(1157121, 143446, 25754, '<td valign="top">Very original idea for this challenge, and I can totally see this one ribboning. Excellent work.</td>', 'Very original idea for this challenge, and I can totally see this one ribboning. Excellent work.', '2005-02-08 11:01:41.000000', NULL, 1),
(1157124, 143559, 8522, '<td valign="top">The border should not take attention away from the photo. This border is way too distracting.</td>', 'The border should not take attention away from the photo. This border is way too distracting.', '2005-02-08 11:02:50.000000', NULL, 1),
(1157127, 144369, 10985, '<td valign="top">Great lighting: the texture really comes out well.</td>', 'Great lighting: the texture really comes out well.', '2005-02-08 11:03:37.000000', NULL, 1),
(1157130, 144362, 8522, '<td valign="top">Focus seems a bit off... it should be on the eyes, not the hair. Nice composition.</td>', 'Focus seems a bit off... it should be on the eyes, not the hair. Nice composition.', '2005-02-08 11:04:15.000000', NULL, 1),
(1157131, 143775, 25754, '<td valign="top">Fantastic way to present Pepto-Bismol!</td>', 'Fantastic way to present Pepto-Bismol!', '2005-02-08 11:04:28.000000', NULL, 1),
(1157132, 143683, 10985, '<td valign="top">Nice sharpness and detail. Great lighting and a dynamic pose.</td>', 'Nice sharpness and detail. Great lighting and a dynamic pose.', '2005-02-08 11:05:26.000000', NULL, 1),
(1157133, 143664, 30712, '<td valign="top">A very successful use of shadow.  Well seen.</td>', 'A very successful use of shadow.  Well seen.', '2005-02-08 11:06:00.000000', NULL, 1),
(1157135, 143748, 8522, '<td valign="top">Clever concept. Would have been wonderful with better lighting and a more simple high-impact composition.</td>', 'Clever concept. Would have been wonderful with better lighting and a more simple high-impact composition.', '2005-02-08 11:06:43.000000', NULL, 1),
(1157136, 144520, 10985, '<td valign="top">As in Voyeur? Nice touch to have yourself in the frame.</td>', 'As in Voyeur? Nice touch to have yourself in the frame.', '2005-02-08 11:06:50.000000', NULL, 1),
(1157140, 144229, 8522, '<td valign="top">White background doesn''t do it for me here, and makes me think it was removed in PS (even if it was in fact just a cloudy day). Light on flower seems too dull and flat.</td>', 'White background doesn''t do it for me here, and makes me think it was removed in PS (even if it was in fact just a cloudy day). Light on flower seems too dull and flat.', '2005-02-08 11:08:15.000000', NULL, 1),
(1157141, 144471, 10985, '<td valign="top">Very nice blurring of the pink. Only her face is sharp, and this brings her eyes out very well. She''s a sweetie, isn''t she?</td>', 'Very nice blurring of the pink. Only her face is sharp, and this brings her eyes out very well. She''s a sweetie, isn''t she?', '2005-02-08 11:08:27.000000', NULL, 1),
(1157144, 143832, 8522, '<td valign="top">Looks a bit too Photoshopped for my taste.</td>', 'Looks a bit too Photoshopped for my taste.', '2005-02-08 11:09:56.000000', NULL, 1),
(1157145, 143856, 8522, '<td valign="top">Nice idea, but the expression really lets the photo down.</td>', 'Nice idea, but the expression really lets the photo down.', '2005-02-08 11:10:35.000000', NULL, 1),
(1157148, 144516, 10985, '<td valign="top">This is beautiful. I understand the statement about softness, but I feel that the eyes (or at least one of them) should be in perfect focus.</td>', 'This is beautiful. I understand the statement about softness, but I feel that the eyes (or at least one of them) should be in perfect focus.', '2005-02-08 11:11:51.000000', NULL, 1),
(1157152, 144413, 8522, '<td valign="top">The sloping horizon bothers me. You could use the distort tool in PS to level the horizon and keep the tree vertical. Great colours.</td>', 'The sloping horizon bothers me. You could use the distort tool in PS to level the horizon and keep the tree vertical. Great colours.', '2005-02-08 11:12:55.000000', NULL, 1),
(1157154, 143943, 8522, '<td valign="top">Great idea, wish the bottom heart was in focus.</td>', 'Great idea, wish the bottom heart was in focus.', '2005-02-08 11:13:23.000000', NULL, 1),
(1157155, 144051, 10985, '<td valign="top">Very elegant and stunning. That black background really lets the viewer focus on the beautiful pose and lighting. Great shot!</td>', 'Very elegant and stunning. That black background really lets the viewer focus on the beautiful pose and lighting. Great shot!', '2005-02-08 11:13:57.000000', NULL, 1),
(1157156, 144265, 8522, '<td valign="top">Huh?! Interesting juxtaposition of opposite colours.</td>', 'Huh?! Interesting juxtaposition of opposite colours.', '2005-02-08 11:15:05.000000', NULL, 1),
(1157157, 144490, 10985, '<td valign="top">Funny and very well done. Sharp and neat and very well lit.</td>', 'Funny and very well done. Sharp and neat and very well lit.', '2005-02-08 11:15:10.000000', NULL, 1),
(1157162, 142430, 8522, '<td valign="top">Great concept. Top left-bottom right diagonals usually complement a photo better though.</td>', 'Great concept. Top left-bottom right diagonals usually complement a photo better though.', '2005-02-08 11:19:21.000000', NULL, 1),
(1157164, 143954, 8522, '<td valign="top">Distort tool in PS could have leveled the bottom of the building. The man really needs to be on one of the 3rds intersections. Great contrasting colours.</td>', 'Distort tool in PS could have leveled the bottom of the building. The man really needs to be on one of the 3rds intersections. Great contrasting colours.', '2005-02-08 11:21:21.000000', NULL, 1),
(1157166, 143029, 8522, '<td valign="top">Well centered shot, let down by poor light, and distracting background.</td>', 'Well centered shot, let down by poor light, and distracting background.', '2005-02-08 11:23:49.000000', NULL, 1),
(1157169, 143845, 8522, '<td valign="top">Selective desat has resulted in a bit of an ugly effect here IMO.</td>', 'Selective desat has resulted in a bit of an ugly effect here IMO.', '2005-02-08 11:24:25.000000', NULL, 1),
(1157186, 143995, 18485, '<td valign="top">it doesn''t get pinker than this!!  great shot.  10</td>', 'it doesn''t get pinker than this!!  great shot.  10', '2005-02-08 11:38:18.000000', NULL, 1),
(1157223, 143740, 27375, '<td valign="top">Nice title and I like the simplicity of this. Well done.</td>', 'Nice title and I like the simplicity of this. Well done.', '2005-02-08 12:14:25.000000', NULL, 1),
(1157261, 144274, 24065, '<td valign="top">Super photo!  I love the composition.  And the fish looking right at the camera is just great!  I hope people aren''t deducting points since the main subject is yellow -- it definitely meets the challenge in my opinion.</td>', 'Super photo!  I love the composition.  And the fish looking right at the camera is just great!  I hope people aren''t deducting points since the main subject is yellow -- it definitely meets the challenge in my opinion.', '2005-02-08 12:38:23.000000', NULL, 1),
