(1158227, 144407, 4285, '<td valign="top">Self-portrait? The light in this shot seems a bit harsh according to the bright areas, ie. knees, rim of glass - reflectors or difusers of some sort may have helped. Also the wrinkled white sheet backdrop takes away from the image. Otherwise, the composition is decent and the pink theme is certainly adhered to. Hope this helps.</td>', 'Self-portrait? The light in this shot seems a bit harsh according to the bright areas, ie. knees, rim of glass - reflectors or difusers of some sort may have helped. Also the wrinkled white sheet backdrop takes away from the image. Otherwise, the composition is decent and the pink theme is certainly adhered to. Hope this helps.', '2005-02-08 20:53:38.000000', NULL, 1),
(1158230, 144335, 23478, '<td valign="top">Wonderful, the lighting is great.</td>', 'Wonderful, the lighting is great.', '2005-02-08 20:54:13.000000', NULL, 1),
