(1159393, 144301, 13156, '<td valign="top">NIce use of selective desaturation ... like it a lot. Model a bit too centered for me .... 7.</td>', 'NIce use of selective desaturation ... like it a lot. Model a bit too centered for me .... 7.', '2005-02-09 09:42:42.000000', NULL, 1),
(1159438, 144392, 13156, '<td valign="top">Shame the shadow of the fruit is cropped of the image. 5.</td>', 'Shame the shadow of the fruit is cropped of the image. 5.', '2005-02-09 10:07:56.000000', NULL, 1),
(1159472, 143461, 24065, '<td valign="top">Very creative and well executed idea!</td>', 'Very creative and well executed idea!', '2005-02-09 10:22:37.000000', NULL, 1),
(1159567, 144250, 20115, '<td valign="top">Just beautiful, but a little less pink on the eyes would have made this awesome.</td>', 'Just beautiful, but a little less pink on the eyes would have made this awesome.', '2005-02-09 11:04:21.000000', NULL, 1),
(1159657, 143446, 5955, '<td valign="top">Excellent Lighting!</td>', 'Excellent Lighting!', '2005-02-09 11:53:56.000000', NULL, 1),
