INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1189466, 142443, 12253, '<td valign="top">I sent you an email about this, but I wanted to leave a comment on the photo.  I think this is really great--I like all the different sources of pink, including the blush on your daughter''s cheeks.  I especially like the way it''s composed here--the way she fits in with the background.  I see what others are saying about the shadow, but I didn''t even notice it until I read the other comments, so while I think it would improve the photo to control them, I don''t think it is an issue here.<br/></td>', 'I sent you an email about this, but I wanted to leave a comment on the photo.  I think this is really great--I like all the different sources of pink, including the blush on your daughter''s cheeks.  I especially like the way it''s composed here--the way she fits in with the background.  I see what others are saying about the shadow, but I didn''t even notice it until I read the other comments, so while I think it would improve the photo to control them, I don''t think it is an issue here.', '2005-02-22 23:10:39.000000', NULL, 0),
(1189490, 142986, 19708, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by mocabela:</b></div><hr/><i> I know people probably don''t want to look at an extreme close up of a chubby face..</i></td></tr></table> <br/><b>Julia!</b> This is not a chubby face. It''s a gorgeous face, complimented by a genuinely nice smile and beautiful hands.<br/>Don''t sell yourself short!</td>', 'Originally posted by mocabela: I know people probably don''t want to look at an extreme close up of a chubby face.. Julia! This is not a chubby face. It''s a gorgeous face, complimented by a genuinely nice smile and beautiful hands.Don''t sell yourself short!', '2005-02-22 23:23:33.000000', NULL, 0),
(1195201, 144009, 19035, '<td valign="top">Kylie, your a car buff, it seems based on whats in your profile, i think your shots are great, escpecially this pink one, what do you think of this one?  It was taken by my son....<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=150351" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/19035/thumb/150351.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/19035/thumb/150351.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/19035/thumb/150351.jpg"/></a></td>', 'Kylie, your a car buff, it seems based on whats in your profile, i think your shots are great, escpecially this pink one, what do you think of this one?  It was taken by my son.... ', '2005-02-26 02:02:40.000000', NULL, 0),
